validator:
function validate(input) {
  const [{ Playback = [], Ads = [] }] = input;
  const sessions = new Set(), ads = new Set(), byCustomer = new Map();
  for (const row of Playback) {
    if (row.some((v) => v === null)) return 'Playback rows may not contain null.';
    const [id, customer, start, end] = row;
    if (sessions.has(id)) return `session_id ${id} appears twice in Playback.`;
    sessions.add(id);
    if (start > end) return `Session ${id} ends before it starts.`;
    if (!byCustomer.has(customer)) byCustomer.set(customer, []);
    byCustomer.get(customer).push([start, end]);
  }
  for (const [customer, spans] of byCustomer) {
    spans.sort((a, b) => a[0] - b[0]);
    for (let i = 1; i < spans.length; i++) if (spans[i][0] <= spans[i - 1][1]) return `Two sessions of customer ${customer} overlap.`;
  }
  for (const row of Ads) {
    if (row.some((v) => v === null)) return 'Ads rows may not contain null.';
    if (ads.has(row[0])) return `ad_id ${row[0]} appears twice in Ads.`;
    ads.add(row[0]);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const customers = small ? 3 : 60;
  const sessionCount = small ? pick(9) : 2000;
  const adCount = small ? pick(9) : 2000;
  // Each customer's sessions are laid out left to right with a gap, so they never overlap.
  const cursor = Array.from({ length: customers + 1 }, () => pick(small ? 4 : 10));
  const Playback = [];
  for (let i = 0; i < sessionCount; i++) {
    const customer = 1 + pick(customers);
    const start = cursor[customer] + 1 + pick(small ? 3 : 20);
    const end = start + pick(small ? 6 : 40);
    cursor[customer] = end;
    Playback.push([0, customer, start, end]);
  }
  // Shuffle the rows, then number them, so ids do not follow time order.
  for (let i = Playback.length - 1; i > 0; i--) { const j = pick(i + 1); [Playback[i], Playback[j]] = [Playback[j], Playback[i]]; }
  Playback.forEach((row, i) => { row[0] = i + 1; });
  const Ads = [];
  for (let i = 0; i < adCount; i++) {
    let customer, timestamp;
    if (Playback.length > 0 && rand() < 0.6) {
      // Aim at a session: inside it, on an edge, or just outside an edge.
      const [, owner, start, end] = Playback[pick(Playback.length)];
      customer = rand() < 0.85 ? owner : 1 + pick(customers + 1);
      timestamp = [start, end, start - 1, end + 1, start + pick(end - start + 1)][pick(5)];
    } else {
      customer = 1 + pick(customers + 1);
      timestamp = pick(small ? 30 : 5000);
    }
    Ads.push([i + 1, customer, timestamp]);
  }
  return [{ Playback, Ads }];
}
